    // ------------------------------------------------------------------
    // 764（1.20.2）向け（クライアント行き）。763向けの各メソッドと
    // 同じペイロード形式だが、番号は *_764 の表、NBT は名前なしのまま。
    // ------------------------------------------------------------------

    /**
     * Chunk Data（765 → 764）のペイロードを変換する。
     * 高さマップ・ブロックエンティティの NBT は764も名前なしのため
     * 書き直さない。バイオームパレットはそのまま通す（順序は同一）。
     * 読めない場合は元のペイロードをそのまま返す。
     */
    public static byte[] translateChunkData765To764(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            int chunkX = reader.readInt();
            int chunkZ = reader.readInt();
            Nbt.ReadResult heightmaps = reader.readAnonymousNbt();
            int dataLength = reader.readVarInt();
            byte[] chunkData = reader.readBytes(dataLength);
            byte[] translatedSections = translateChunkSections(chunkData, TARGET_764);
            int blockEntityCount = reader.readVarInt();
            List<BlockEntityEntry> kept = new ArrayList<>();
            for (int i = 0; i < blockEntityCount; i++) {
                int packedXZ = reader.readUnsignedByte();
                int y = reader.readShort();
                int type = reader.readVarInt();
                Tag nbt = readOptionalAnonymousNbt(reader);
                int mapped = RegistryRemapper.mapBlockEntityType(type, TARGET_764);
                if (mapped == RegistryRemapper.DROP) {
                    LOG.warning("764に無いブロックエンティティ種別（765 type=" + type
                            + "）のエントリをチャンクから落とします。");
                    continue;
                }
                kept.add(new BlockEntityEntry(packedXZ, y, mapped, nbt));
            }
            byte[] lightData = reader.rest();
            Writer writer = new Writer();
            writer.writeInt(chunkX);
            writer.writeInt(chunkZ);
            if (heightmaps.tag() == null) {
                writer.writeByte(0);
            } else {
                writer.writeAnonymousNbt(heightmaps.tag());
            }
            writer.writeByteArray(translatedSections);
            writer.writeVarInt(kept.size());
            for (BlockEntityEntry entry : kept) {
                writer.writeUnsignedByte(entry.packedXZ());
                writer.writeShort(entry.y());
                writer.writeVarInt(entry.type());
                writeOptionalAnonymousNbt(writer, entry.nbt());
            }
            writer.writeBytes(lightData);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Chunk Data を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /** Block Change（765 → 764）：位置＋ブロック状態ID。 */
    public static byte[] translateBlockChange765To764(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            long position = reader.readPositionRaw();
            int state = reader.readVarInt();
            requireEnd(reader);
            Writer writer = new Writer();
            writer.writePositionRaw(position);
            writer.writeVarInt(RegistryRemapper.mapBlockState(state, TARGET_764));
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Block Change を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /** Multi Block Change（765 → 764）。 */
    public static byte[] translateMultiBlockChange765To764(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            long chunkCoordinates = reader.readLong();
            int count = reader.readVarInt();
            if (count < 0) {
                throw new IllegalArgumentException("Multi Block Change の件数が負です: " + count);
            }
            Writer writer = new Writer();
            writer.writeLong(chunkCoordinates);
            writer.writeVarInt(count);
            for (int i = 0; i < count; i++) {
                int record = reader.readVarInt();
                int state = record >>> 12;
                int local = record & 0xFFF;
                writer.writeVarInt((RegistryRemapper.mapBlockState(state, TARGET_764) << 12) | local);
            }
            requireEnd(reader);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Multi Block Change を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /**
     * Block Entity Data（765 → 764）。
     * 764に無い種別（crafter／trial_spawner）の場合は {@code null}
     * を返し、呼び出し側はパケットごと落とすこと。
     */
    public static byte[] translateBlockEntityData765To764(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            long position = reader.readPositionRaw();
            int type = reader.readVarInt();
            Tag nbt = readOptionalAnonymousNbt(reader);
            requireEnd(reader);
            int mapped = RegistryRemapper.mapBlockEntityType(type, TARGET_764);
            if (mapped == RegistryRemapper.DROP) {
                LOG.warning("764に無いブロックエンティティ種別（765 type=" + type
                        + "）の Block Entity Data を落とします。");
                return null;
            }
            Writer writer = new Writer();
            writer.writePositionRaw(position);
            writer.writeVarInt(mapped);
            writeOptionalAnonymousNbt(writer, nbt);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Block Entity Data を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

