            writer.writeVarInt(type == FALLING_BLOCK_765
                    ? RegistryRemapper.mapBlockState(objectData, TARGET_764) : objectData);
            writer.writeShort(velX);
            writer.writeShort(velY);
            writer.writeShort(velZ);
