            if (count < 0) {
                throw new IllegalArgumentException("Window Items の個数が負です: " + count);
            }
            writer.writeVarInt(count);
            for (int i = 0; i < count; i++) {
                translateSlot764To765(reader, writer);
            }
            translateSlot764To765(reader, writer);
            requireEnd(reader);
            return writer.bytes();
