    /**
     * Spawn Entity（764 → 765）。種別IDを上向きに変換する。
     * falling_block の objectData はブロック状態IDなので一緒に変換する
     * （764の falling_block=36 が765では37になる。種別を上向きに
     * 変換した結果で判定するため、764側の番号を覚えておく必要は無い）。
     */
    public static byte[] translateSpawnEntity764To765(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            int entityId = reader.readVarInt();
            byte[] uuid = reader.readBytes(16);
            int type = reader.readVarInt();
            double x = reader.readDouble();
            double y = reader.readDouble();
            double z = reader.readDouble();
            int pitch = reader.readByte();
            int yaw = reader.readByte();
            int headPitch = reader.readByte();
            int objectData = reader.readVarInt();
            int velX = reader.readShort();
            int velY = reader.readShort();
            int velZ = reader.readShort();
            requireEnd(reader);
            int upType = RegistryRemapper.mapEntityTypeUp764(type);
            Writer writer = new Writer();
            writer.writeVarInt(entityId);
            writer.writeBytes(uuid);
            writer.writeVarInt(upType);
            writer.writeDouble(x);
            writer.writeDouble(y);
            writer.writeDouble(z);
            writer.writeByte(pitch);
            writer.writeByte(yaw);
            writer.writeByte(headPitch);
            writer.writeVarInt(upType == FALLING_BLOCK_765
                    ? RegistryRemapper.mapBlockStateUp764(objectData) : objectData);
            writer.writeShort(velX);
            writer.writeShort(velY);
            writer.writeShort(velZ);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Spawn Entity を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /** Entity Metadata（764 → 765）。スロット・ブロック状態・粒子・テキストを変換する。 */
    public static byte[] translateEntityMetadata764To765(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            Writer writer = new Writer();
            writer.writeVarInt(reader.readVarInt());
            while (true) {
                int index = reader.readUnsignedByte();
                if (index == 0xFF) {
                    writer.writeUnsignedByte(0xFF);
                    break;
                }
                int type = reader.readVarInt();
                // variant 系（22 猫・23 狼・24 カエル・26 絵画）は764と765で
                // 形式が同じ（protocol.json の entityMetadataItem が
                // component・particle 以外同一）のため、そのまま通す。
                // holder 形式（23／26）の直書き（0）の場合は中身の NBT も
                // そのまま写す（両方とも名前なし）。
                if (type == 22 || type == 24) {
                    int variant = reader.readVarInt();
                    writer.writeUnsignedByte(index);
                    writer.writeVarInt(type);
                    writer.writeVarInt(variant);
                    continue;
                }
                if (type == 23 || type == 26) {
                    int holder = reader.readVarInt();
                    Tag inline = holder == 0 ? reader.readAnonymousNbt().tag() : null;
                    writer.writeUnsignedByte(index);
                    writer.writeVarInt(type);
                    writer.writeVarInt(holder);
                    if (holder == 0) {
                        writeOptionalAnonymousNbt(writer, inline);
                    }
                    continue;
                }
                writer.writeUnsignedByte(index);
                writer.writeVarInt(type);
                translateMetadataValueUp(reader, writer, type);
            }
            requireEnd(reader);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Entity Metadata を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /**
     * メタデータの値1個を764→765向けに変換する。型番号は wiki.vg の
     * Entity Metadata（1.20.2）による。variant 系（22／23／24／26）は
     * 呼び出し側で扱うため、ここには来ない。テキスト（5／6）は764の
     * JSON 文字列から765の NBT へ変換する。
     */
    private static void translateMetadataValueUp(Reader reader, Writer writer, int type) {
        switch (type) {
            case 0 -> writer.writeByte(reader.readByte());
            case 1 -> writer.writeVarInt(reader.readVarInt());
            case 2 -> writer.writeVarLong(reader.readVarLong());
            case 3 -> writer.writeFloat(reader.readFloat());
            case 4 -> writer.writeString(reader.readString());
            case 5 -> writer.writeAnonymousNbt(JsonToNbt.fromJson(reader.readString()));
            case 6 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writeAnonymousNbt(JsonToNbt.fromJson(reader.readString()));
                }
            }
            case 7 -> translateSlot764To765(reader, writer);
            case 8 -> writer.writeBoolean(reader.readBoolean());
            case 9 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            case 10 -> writer.writePositionRaw(reader.readPositionRaw());
            case 11 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writePositionRaw(reader.readPositionRaw());
                }
            }
            case 12 -> writer.writeVarInt(reader.readVarInt());
            case 13 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writeBytes(reader.readBytes(16));
                }
            }
            case 14 -> writer.writeVarInt(RegistryRemapper.mapBlockStateUp764(reader.readVarInt()));
            case 15 -> {
                // 0 は「無し」。それ以外はブロック状態ID。
                int state = reader.readVarInt();
                writer.writeVarInt(state == 0 ? 0 : RegistryRemapper.mapBlockStateUp764(state));
            }
            case 16 -> writeOptionalAnonymousNbt(writer, reader.readAnonymousNbt().tag());
            case 17 -> translateParticleUp(reader, writer);
            case 18 -> {
                int count = reader.readVarInt();
                writer.writeVarInt(count);
                for (int i = 0; i < count; i++) {
                    translateParticleUp(reader, writer);
                }
            }
            case 19 -> {
                writer.writeVarInt(reader.readVarInt());
                writer.writeVarInt(reader.readVarInt());
                writer.writeVarInt(reader.readVarInt());
            }
            case 20 -> writer.writeVarInt(reader.readVarInt());
            case 21 -> writer.writeVarInt(reader.readVarInt());
            case 27 -> writer.writeVarInt(reader.readVarInt());
            case 25 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writeString(reader.readString());
                    writer.writePositionRaw(reader.readPositionRaw());
                }
            }
            case 28 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            case 29 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            default -> throw new IllegalArgumentException("未知のメタデータ型です: " + type);
        }
    }

