    /**
     * 音の Holder を764→765向けに書き直す。直書き（0）の音の名前は
     * 764の名前がそのまま765でも使えるためそのまま通す。
     * レジストリ番号（0以外）は上向きに変換する（＋1 された値）。
     */
    private static void translateSoundHolderUp(Reader reader, Writer writer) {
        int holder = reader.readVarInt();
        if (holder == 0) {
            writer.writeVarInt(0);
            writer.writeString(RegistryRemapper.mapSoundNameUp764(reader.readString()));
            boolean hasRange = reader.readBoolean();
            writer.writeBoolean(hasRange);
            if (hasRange) {
                writer.writeFloat(reader.readFloat());
            }
            return;
        }
        writer.writeVarInt(RegistryRemapper.mapSoundUp764(holder - 1) + 1);
    }

    /** Stop Sound（764 → 765）。音の名前はそのまま通す（764の名前は765にもある）。 */
    public static byte[] translateStopSound764To765(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            int flags = reader.readByte();
            Writer writer = new Writer();
            writer.writeByte(flags);
            if ((flags & 0x01) != 0) {
                writer.writeVarInt(reader.readVarInt());
            }
            if ((flags & 0x02) != 0) {
                writer.writeString(RegistryRemapper.mapSoundNameUp764(reader.readString()));
            }
            requireEnd(reader);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Stop Sound を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

