    // ------------------------------------------------------------------
    // 766（1.20.5／1.20.6）向け（クライアント行き：765サーバー→766クライアント）。
    // スロットはコンポーネント形式のため NBT は落とす。パーティクル・
    // メタデータの型番号は 766 のものを使う。
    // ------------------------------------------------------------------

    /**
     * 765のスロット1個を766向けに読む。766のスロットは [個数 i8]
     * [id VarInt][追加 0][削除 0]。NBT は 766に無い形式のため落とす
     * （エンチャント・名前・カスタムデータは失われる。IDと個数だけ通す）。
     */
    private static void translateSlot765To766(Reader reader, Writer writer) {
        boolean present = reader.readBoolean();
        if (!present) {
            writer.writeByte(0);
            return;
        }
        int item = RegistryRemapper.mapItem766(reader.readVarInt());
        int count = reader.readByte();
        Tag nbt = readOptionalAnonymousNbt(reader);
        if (nbt != null) {
            logOnce("slot-nbt-765to766",
                    "765のスロットの NBT を766向けに落とします（コンポーネント形式のため変換できません）。");
        }
        writer.writeByte(count);
        writer.writeVarInt(item);
        writer.writeVarInt(0);
        writer.writeVarInt(0);
    }

    /**
     * 765の取引の入力（スロット）を766の ItemCost 形式で書く。
     * [id VarInt][個数 VarInt][追加 0]。空きの入力は air（0）・0個にする。
     */
    private static void translateItemCost765To766(Reader reader, Writer writer) {
        boolean present = reader.readBoolean();
        if (!present) {
            writer.writeVarInt(0);
            writer.writeVarInt(0);
            writer.writeVarInt(0);
            return;
        }
        int item = RegistryRemapper.mapItem766(reader.readVarInt());
        int count = reader.readByte();
        Tag nbt = readOptionalAnonymousNbt(reader);
        if (nbt != null) {
            logOnce("slot-nbt-765to766",
                    "765のスロットの NBT を766向けに落とします（コンポーネント形式のため変換できません）。");
        }
        writer.writeVarInt(item);
        writer.writeVarInt(count);
        writer.writeVarInt(0);
    }

    /**
     * 765の取引の入力2（任意のスロット）を766の option 付き ItemCost
     * 形式で書く。空きなら false だけ書く。
     */
    private static void translateOptionalItemCost765To766(Reader reader, Writer writer) {
        boolean present = reader.readBoolean();
        writer.writeBoolean(present);
        if (!present) {
            return;
        }
        int item = RegistryRemapper.mapItem766(reader.readVarInt());
        int count = reader.readByte();
        Tag nbt = readOptionalAnonymousNbt(reader);
        if (nbt != null) {
            logOnce("slot-nbt-765to766",
                    "765のスロットの NBT を766向けに落とします（コンポーネント形式のため変換できません）。");
        }
        writer.writeVarInt(item);
        writer.writeVarInt(count);
        writer.writeVarInt(0);
    }

    /**
     * パーティクル1個（ID VarInt＋データ）を765→766向けに変換する。
     * データの形式は minecraft-data の protocol.json の particleData
     * （765側のキー）で読む。766側のIDで書く。
     * 765の ambient_entity_effect（0）は 766の entity_effect（20）に
     * なり、766側は色の i32 が要るため 0 を書く（765側に色の情報が無い）。
     */
    private static void translateParticle765To766(Reader reader, Writer writer) {
        int particleId = reader.readVarInt();
        writer.writeVarInt(RegistryRemapper.mapParticle766(particleId));
        switch (particleId) {
            case 0 -> writer.writeInt(0); // ambient_entity_effect → entity_effect：色は不明のため 0
            case 21 -> writer.writeInt(0); // entity_effect：765に色のデータが無いため 0 を合成する（766は i32 が要る）
            case 2, 3, 27 -> // block, block_marker, falling_dust：ブロック状態ID
                    writer.writeVarInt(RegistryRemapper.mapBlockState766(reader.readVarInt()));
            case 14 -> { // dust：赤・緑・青・大きさ
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            case 15 -> { // dust_color_transition：7個の float
                for (int i = 0; i < 7; i++) {
                    writer.writeFloat(reader.readFloat());
                }
            }
            case 33 -> writer.writeFloat(reader.readFloat()); // sculk_charge：回転（1個の float）
            case 42 -> translateSlot765To766(reader, writer); // item
            case 43 -> translateVibration765To766(reader, writer); // vibration
            case 96 -> writer.writeVarInt(reader.readVarInt()); // shriek：遅延 tick 数
            default -> {
                // その他の粒子にデータは無い。
            }
        }
    }

    /**
     * vibration 粒子を765→766向けに変換する。765は [種別文字列]
     * [entity なら entityId・eyeHeight・destination の VarInt 3個]
     * [block なら位置][tick 数]、766は [種別 VarInt（0＝block／1＝entity）]
     * [entity なら entityId VarInt＋eyeHeight f32][tick 数]。
     * 765の destination（3個目の VarInt）は 766に無いため落とす。
     * 765の eyeHeight は minecraft-data では VarInt だが、実バニラでの
     * 確認は未実施のため、値だけ float にして通す。
     */
    private static void translateVibration765To766(Reader reader, Writer writer) {
        String positionType = reader.readString();
        if ("minecraft:block".equals(positionType)) {
            long position = reader.readPositionRaw();
            int ticks = reader.readVarInt();
            writer.writeVarInt(0);
            writer.writePositionRaw(position);
            writer.writeVarInt(ticks);
            return;
        }
        if ("minecraft:entity".equals(positionType)) {
            int entityId = reader.readVarInt();
            int eyeHeight = reader.readVarInt();
            reader.readVarInt(); // destination：766に無いため落とす
            int ticks = reader.readVarInt();
            writer.writeVarInt(1);
            writer.writeVarInt(entityId);
            writer.writeFloat(eyeHeight);
            writer.writeVarInt(ticks);
            return;
        }
        throw new IllegalArgumentException("未知の vibration の位置種別です: " + positionType);
    }

    /** 音の Holder を765→766向けに書き直す。直書きの名前は 766の名前にする。 */
    private static void translateSoundHolder765To766(Reader reader, Writer writer) {
        int holder = reader.readVarInt();
        if (holder == 0) {
            writer.writeVarInt(0);
            writer.writeString(RegistryRemapper.mapSoundName766(reader.readString()));
            boolean hasRange = reader.readBoolean();
            writer.writeBoolean(hasRange);
            if (hasRange) {
                writer.writeFloat(reader.readFloat());
            }
            return;
        }
        writer.writeVarInt(RegistryRemapper.mapSound766(holder - 1) + 1);
    }

    /**
     * メタデータの値1個を765→766向けに変換する。型番号は 765のもの
     * （呼び出し側で 28／29 は 29／30 に付け替える）。テキスト（5／6）と
     * NBT（16）は766も名前なし NBT のためそのまま写す。スロット（7）は
     * 766形式に、粒子（17／18）は 766の粒子形式にする。
     */
    private static void translateMetadataValue765To766(Reader reader, Writer writer, int type) {
        switch (type) {
            case 0 -> writer.writeByte(reader.readByte());
            case 1 -> writer.writeVarInt(reader.readVarInt());
            case 2 -> writer.writeVarLong(reader.readVarLong());
            case 3 -> writer.writeFloat(reader.readFloat());
            case 4 -> writer.writeString(reader.readString());
            case 5 -> {
                Tag tag = reader.readAnonymousNbt().tag();
                if (tag == null) {
                    throw new IllegalArgumentException("メタデータのテキストが空です。");
                }
                writer.writeAnonymousNbt(tag);
            }
            case 6 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    Tag tag = reader.readAnonymousNbt().tag();
                    if (tag == null) {
                        throw new IllegalArgumentException("メタデータのテキストが空です。");
                    }
                    writer.writeAnonymousNbt(tag);
                }
            }
            case 7 -> translateSlot765To766(reader, writer);
            case 8 -> writer.writeBoolean(reader.readBoolean());
            case 9 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            case 10 -> writer.writePositionRaw(reader.readPositionRaw());
            case 11 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writePositionRaw(reader.readPositionRaw());
                }
            }
            case 12 -> writer.writeVarInt(reader.readVarInt());
            case 13 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writeBytes(reader.readBytes(16));
                }
            }
            case 14 -> writer.writeVarInt(RegistryRemapper.mapBlockState766(reader.readVarInt()));
            case 15 -> {
                // 0 は「無し」。それ以外はブロック状態ID。
                int state = reader.readVarInt();
                writer.writeVarInt(state == 0 ? 0 : RegistryRemapper.mapBlockState766(state));
            }
            case 16 -> writeOptionalAnonymousNbt(writer, reader.readAnonymousNbt().tag());
            case 17 -> translateParticle765To766(reader, writer);
            case 18 -> {
                int count = reader.readVarInt();
                writer.writeVarInt(count);
                for (int i = 0; i < count; i++) {
                    translateParticle765To766(reader, writer);
                }
            }
            case 19 -> {
                writer.writeVarInt(reader.readVarInt());
                writer.writeVarInt(reader.readVarInt());
                writer.writeVarInt(reader.readVarInt());
            }
            case 20 -> writer.writeVarInt(reader.readVarInt());
            case 21 -> writer.writeVarInt(reader.readVarInt());
            case 27 -> writer.writeVarInt(reader.readVarInt());
            case 25 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writeString(reader.readString());
                    writer.writePositionRaw(reader.readPositionRaw());
                }
            }
            case 28 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            case 29 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            default -> throw new IllegalArgumentException("未知のメタデータ型です: " + type);
        }
    }

    /** Entity Metadata（765 → 766）。型番号 28／29 は 29／30 に付け替える。 */
    public static byte[] translateEntityMetadata765To766(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            Writer writer = new Writer();
            writer.writeVarInt(reader.readVarInt());
            while (true) {
                int index = reader.readUnsignedByte();
                if (index == 0xFF) {
                    writer.writeUnsignedByte(0xFF);
                    break;
                }
                int type = reader.readVarInt();
                // variant 系（22 猫・24 カエル）は VarInt のまま通す。
                // holder 形式（23 狼・26 絵画）は番号のものだけ通し、
                // 直書き（0）のものは落とす（765の直書きは NBT、
                // 766の直書きは構造化データのため変換できない）。
                if (type == 22 || type == 24) {
                    int variant = reader.readVarInt();
                    writer.writeUnsignedByte(index);
                    writer.writeVarInt(type);
                    writer.writeVarInt(variant);
                    continue;
                }
                if (type == 23 || type == 26) {
                    int holder = reader.readVarInt();
                    if (holder == 0) {
                        reader.readAnonymousNbt();
                        logOnce("metadata-holder-765to766",
                                "765のメタデータの holder 直書き（NBT）を766向けに落とします"
                                        + "（766の直書きは構造化データのため変換できません）。");
                        continue;
                    }
                    writer.writeUnsignedByte(index);
                    writer.writeVarInt(type);
                    writer.writeVarInt(holder);
                    continue;
                }
                writer.writeUnsignedByte(index);
                writer.writeVarInt(type == 28 ? 29 : type == 29 ? 30 : type);
                translateMetadataValue765To766(reader, writer, type);
            }
            requireEnd(reader);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Entity Metadata を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /**
     * Chunk Data（765 → 766）のペイロードを変換する。
     * 高さマップ・ブロックエンティティの NBT は766も名前なしのため
     * 書き直さない。バイオームパレットはそのまま通す（順序は同一）。
     * 読めない場合は元のペイロードをそのまま返す。
     */
    public static byte[] translateChunkData765To766(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            int chunkX = reader.readInt();
            int chunkZ = reader.readInt();
            Nbt.ReadResult heightmaps = reader.readAnonymousNbt();
            int dataLength = reader.readVarInt();
            byte[] chunkData = reader.readBytes(dataLength);
            byte[] translatedSections = translateChunkSections(chunkData, TARGET_766);
            int blockEntityCount = reader.readVarInt();
            List<BlockEntityEntry> kept = new ArrayList<>();
            for (int i = 0; i < blockEntityCount; i++) {
                int packedXZ = reader.readUnsignedByte();
                int y = reader.readShort();
                int type = reader.readVarInt();
                Tag nbt = readOptionalAnonymousNbt(reader);
                int mapped = RegistryRemapper.mapBlockEntityType766(type);
                if (mapped == RegistryRemapper.DROP) {
                    LOG.warning("766に無いブロックエンティティ種別（765 type=" + type
                            + "）のエントリをチャンクから落とします。");
                    continue;
                }
                kept.add(new BlockEntityEntry(packedXZ, y, mapped, nbt));
            }
            byte[] lightData = reader.rest();
            Writer writer = new Writer();
            writer.writeInt(chunkX);
            writer.writeInt(chunkZ);
            if (heightmaps.tag() == null) {
                writer.writeByte(0);
            } else {
                writer.writeAnonymousNbt(heightmaps.tag());
            }
            writer.writeByteArray(translatedSections);
            writer.writeVarInt(kept.size());
            for (BlockEntityEntry entry : kept) {
                writer.writeUnsignedByte(entry.packedXZ());
                writer.writeShort(entry.y());
                writer.writeVarInt(entry.type());
                writeOptionalAnonymousNbt(writer, entry.nbt());
            }
            writer.writeBytes(lightData);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Chunk Data を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /** Block Change（765 → 766）：位置＋ブロック状態ID。 */
    public static byte[] translateBlockChange765To766(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            long position = reader.readPositionRaw();
            int state = reader.readVarInt();
            requireEnd(reader);
            Writer writer = new Writer();
            writer.writePositionRaw(position);
            writer.writeVarInt(RegistryRemapper.mapBlockState766(state));
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Block Change を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /** Multi Block Change（765 → 766）。 */
    public static byte[] translateMultiBlockChange765To766(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            long chunkCoordinates = reader.readLong();
            int count = reader.readVarInt();
            if (count < 0) {
                throw new IllegalArgumentException("Multi Block Change の件数が負です: " + count);
            }
            Writer writer = new Writer();
            writer.writeLong(chunkCoordinates);
            writer.writeVarInt(count);
            for (int i = 0; i < count; i++) {
                int record = reader.readVarInt();
                int state = record >>> 12;
                int local = record & 0xFFF;
                writer.writeVarInt((RegistryRemapper.mapBlockState766(state) << 12) | local);
            }
            requireEnd(reader);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Multi Block Change を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /**
     * Block Entity Data（765 → 766）。
     * 766に無い種別（範囲外）の場合は {@code null} を返し、
     * 呼び出し側はパケットごと落とすこと。
     */
    public static byte[] translateBlockEntityData765To766(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            long position = reader.readPositionRaw();
            int type = reader.readVarInt();
            Tag nbt = readOptionalAnonymousNbt(reader);
            requireEnd(reader);
            int mapped = RegistryRemapper.mapBlockEntityType766(type);
            if (mapped == RegistryRemapper.DROP) {
                LOG.warning("766に無いブロックエンティティ種別（765 type=" + type
                        + "）の Block Entity Data を落とします。");
                return null;
            }
            Writer writer = new Writer();
            writer.writePositionRaw(position);
            writer.writeVarInt(mapped);
            writeOptionalAnonymousNbt(writer, nbt);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Block Entity Data を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

