    /** Trade List（765 → 766）。取引の入力は ItemCost 形式にする。 */
    public static byte[] translateTradeList765To766(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            Writer writer = new Writer();
            writer.writeVarInt(reader.readVarInt());
            int count = reader.readVarInt();
            if (count < 0) {
                throw new IllegalArgumentException("Trade List の件数が負です: " + count);
            }
            writer.writeVarInt(count);
            for (int i = 0; i < count; i++) {
                translateItemCost765To766(reader, writer);
                translateSlot765To766(reader, writer);
                translateOptionalItemCost765To766(reader, writer);
                writer.writeBoolean(reader.readBoolean());
                writer.writeInt(reader.readInt());
                writer.writeInt(reader.readInt());
                writer.writeInt(reader.readInt());
                writer.writeInt(reader.readInt());
                writer.writeFloat(reader.readFloat());
                writer.writeInt(reader.readInt());
            }
            writer.writeVarInt(reader.readVarInt());
            writer.writeVarInt(reader.readVarInt());
            writer.writeBoolean(reader.readBoolean());
            writer.writeBoolean(reader.readBoolean());
            requireEnd(reader);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Trade List を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

