    // ------------------------------------------------------------------
    // 766（1.20.5／1.20.6）向け（クライアント行き：766サーバー→765クライアント）。
    // スロットはコンポーネント付きのものはパケットごと落とす。
    // それ以外のパケットは読めない場合は従来通り素通しする。
    // ------------------------------------------------------------------

    /** チャンクデータ（セクションの列）を766→765向けに変換する。 */
    static byte[] translateChunkSectionsUp766(byte[] data) {
        Reader reader = new Reader(data);
        Writer writer = new Writer();
        while (reader.remaining() > 0) {
            int blockCount = reader.readShort();
            writer.writeShort(blockCount);
            translatePalettedContainerUp766(reader, writer, true);
            translatePalettedContainerUp766(reader, writer, false);
        }
        return writer.bytes();
    }

    /**
     * パレット付きコンテナ1個を766→765向けに変換する。
     * 下向きの {@link #translatePalettedContainer(Reader, Writer, boolean, int)}
     * と対称：シングル／間接パレットの値は上向きに変換し、直接パレットは
     * 各エントリを上向きに変換して詰め直す。バイオームはそのまま通す。
     */
    static void translatePalettedContainerUp766(Reader reader, Writer writer, boolean blocks) {
        int bitsPerEntry = reader.readUnsignedByte();
        if (bitsPerEntry > 32) {
            throw new IllegalArgumentException("Bits Per Entry が大きすぎます: " + bitsPerEntry);
        }
        writer.writeUnsignedByte(bitsPerEntry);
        int entryCount = blocks ? 4096 : 64;
        if (bitsPerEntry == 0) {
            int value = reader.readVarInt();
            writer.writeVarInt(blocks ? RegistryRemapper.mapBlockStateUp766(value) : value);
            int dataLength = reader.readVarInt();
            if (dataLength != 0) {
                throw new IllegalArgumentException(
                        "シングルパレットの Data Array 長が 0 ではありません: " + dataLength);
            }
            writer.writeVarInt(0);
            return;
        }
        boolean indirect = blocks ? bitsPerEntry <= 8 : bitsPerEntry <= 3;
        if (indirect) {
            int paletteLength = reader.readVarInt();
            if (paletteLength <= 0 || paletteLength > (1 << bitsPerEntry)) {
                throw new IllegalArgumentException("パレット長が不正です: " + paletteLength);
            }
            writer.writeVarInt(paletteLength);
            for (int i = 0; i < paletteLength; i++) {
                int value = reader.readVarInt();
                writer.writeVarInt(blocks ? RegistryRemapper.mapBlockStateUp766(value) : value);
            }
            copyLongArray(reader, writer);
            return;
        }
        int dataLength = reader.readVarInt();// バニラの BitStorage はエントリを long の境界をまたいで連続して詰めるため、

        // long 数は (entryCount * bitsPerEntry + 63) / 64。旧式の

        // (entryCount + perLong - 1) / perLong（perLong = 64 / bits）は bits が 64 を

        // 割り切らないとき（3・5・6・7・9…）に多めに数え、後続のコンテナがずれて

        // 読めなくなる（2026-11-14、26.1のBedrockマトリクスで発覚）。

        int expected = (entryCount * bitsPerEntry + 63) / 64;
        if (dataLength != expected) {
            throw new IllegalArgumentException("直接パレットの Data Array 長が想定と違います: "
                    + dataLength + "（想定=" + expected + "）。");
        }
        writer.writeVarInt(dataLength);
        long[] longs = new long[dataLength];
        for (int i = 0; i < dataLength; i++) {
            longs[i] = reader.readLong();
        }
        if (blocks) {
            remapDirectEntriesUp766(longs, bitsPerEntry, entryCount);
        }
        for (long value : longs) {
            writer.writeLong(value);
        }
    }

    /** 直接パレットの long 列の中の各エントリをブロック状態IDとして上向きに変換する。 */
    private static void remapDirectEntriesUp766(long[] longs, int bitsPerEntry, int entryCount) {
        long mask = (1L << bitsPerEntry) - 1;
        // エントリは long の境界をまたぐことがある（bits が 64 を割り切らないとき）。
        // BitStorage.get と同じく、またぐ分は次の long の下位ビットから取る。
        // 旧式の「1 long あたり perLong 個を先頭から読む」は、またぐエントリの
        // 上位ビットを落として誤った値を返していた（2026-11-14）。
        int needed = (entryCount * bitsPerEntry + 63) / 64;
        if (longs.length < needed) {
            throw new IllegalArgumentException(
                    "直接パレットの Data Array 長が想定より短いです（渡された=" + longs.length + "、想定=" + needed + "）。");
        }
        int[] entries = new int[entryCount];
        int bitPos = 0;
        for (int index = 0; index < entryCount; index++) {
            int cellIndex = bitPos >> 6;
            int bitIndex = bitPos & 63;
            long low = longs[cellIndex];
            int entry;
            if (bitIndex + bitsPerEntry <= 64) {
                entry = (int) ((low >>> bitIndex) & mask);
            } else {
                int lowBits = 64 - bitIndex;
                long high = cellIndex + 1 < longs.length ? longs[cellIndex + 1] : 0L;
                entry = (int) (((low >>> bitIndex) | (high << lowBits)) & mask);
            }
            entries[index] = entry;
            bitPos += bitsPerEntry;
        }
        for (int i = 0; i < longs.length; i++) {
            longs[i] = 0L;
        }
        bitPos = 0;
        for (int index = 0; index < entryCount; index++) {
            int mapped = RegistryRemapper.mapBlockStateUp766(entries[index]);
            int cellIndex = bitPos >> 6;
            int bitIndex = bitPos & 63;
            longs[cellIndex] |= ((long) mapped & mask) << bitIndex;
            if (bitIndex + bitsPerEntry > 64) {
                int lowBits = 64 - bitIndex;
                longs[cellIndex + 1] |= ((long) mapped & mask) >>> lowBits;
            }
            bitPos += bitsPerEntry;
        }
    }

    /**
     * 766のスロット1個を765向けに読む。追加・削除のコンポーネントが
     * 両方 0 のものだけ IDと個数で通す。コンポーネント付きのスロットは
     * 読み飛ばせない（型ごとの形式が必要なため）ので
     * {@link DropPacketException} を投げ、呼び出し側はパケットごと落とす。
     */
    private static void translateSlot766To765(Reader reader, Writer writer) {
        int count = reader.readByte();
        if (count == 0) {
            writer.writeBoolean(false);
            return;
        }
        if (count < 0) {
            throw new IllegalArgumentException("766のスロットの個数が負です: " + count);
        }
        int item = RegistryRemapper.mapItemReverse766(reader.readVarInt());
        int added = reader.readVarInt();
        int removed = reader.readVarInt();
        if (added != 0 || removed != 0) {
            throw new DropPacketException(
                    "766のスロットにコンポーネントがあるため765向けに変換できません"
                            + "（追加=" + added + "、削除=" + removed + "）。");
        }
        writer.writeBoolean(true);
        writer.writeVarInt(item);
        writer.writeByte(count);
        writer.writeByte(0);
    }

    /**
     * 766の取引の入力（ItemCost）を765のスロット形式で書く。
     * コンポーネント付きの入力は {@link DropPacketException} を投げる。
     * air（id 0）・0個の入力は空きのスロットにする。
     */
    private static void translateItemCost766To765(Reader reader, Writer writer) {
        int item = reader.readVarInt();
        int count = reader.readVarInt();
        int added = reader.readVarInt();
        if (added != 0) {
            throw new DropPacketException(
                    "766の取引の入力にコンポーネントがあるため765向けに変換できません"
                            + "（追加=" + added + "）。");
        }
        // コンポーネントの本体は added=0 のため読むものが無い。
        if (item == 0 || count <= 0) {
            writer.writeBoolean(false);
            return;
        }
        writer.writeBoolean(true);
        writer.writeVarInt(RegistryRemapper.mapItemReverse766(item));
        writer.writeByte(count);
        writer.writeByte(0);
    }

    /**
     * 766の取引の入力2（option 付き ItemCost）を765のスロット形式で書く。
     * 無ければ空きのスロットにする。
     */
    private static void translateOptionalItemCost766To765(Reader reader, Writer writer) {
        boolean present = reader.readBoolean();
        if (!present) {
            writer.writeBoolean(false);
            return;
        }
        translateItemCost766To765(reader, writer);
    }

    /**
     * パーティクル1個（ID VarInt＋データ）を766→765向けに変換する。
     * データの形式は minecraft-data の protocol.json の Particle
     * （766側の data）で読む。765側のIDで書く。
     * 766の entity_effect（20）は 765の entity_effect（21）に
     * なり、765側に色のデータは無いため i32 を読んで落とす。
     * 765の ambient_entity_effect（0）には戻らない（invert は
     * 同名の entity_effect を選ぶ）。
     */
    private static void translateParticle766To765(Reader reader, Writer writer) {
        int particleId = reader.readVarInt();
        writer.writeVarInt(RegistryRemapper.mapParticleUp766(particleId));
        switch (particleId) {
            case 1, 2, 28, 105 -> // block, block_marker, falling_dust, dust_pillar：ブロック状態ID
                    writer.writeVarInt(RegistryRemapper.mapBlockStateUp766(reader.readVarInt()));
            case 13 -> { // dust：赤・緑・青・大きさ
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            case 14 -> { // dust_color_transition：7個の float
                for (int i = 0; i < 7; i++) {
                    writer.writeFloat(reader.readFloat());
                }
            }
            case 20 -> reader.readInt(); // entity_effect：色の i32 を読んで落とす
            case 35 -> writer.writeFloat(reader.readFloat()); // sculk_charge：回転（1個の float）
            case 44 -> translateSlot766To765(reader, writer); // item
            case 45 -> translateVibration766To765(reader, writer); // vibration
            case 99 -> writer.writeVarInt(reader.readVarInt()); // shriek：遅延 tick 数
            default -> {
                // その他の粒子にデータは無い。
            }
        }
    }

    /**
     * vibration 粒子を766→765向けに変換する。766は [種別 VarInt
     * （0＝block／1＝entity）][entity なら entityId VarInt＋eyeHeight f32]
     * [tick 数]、765は [種別文字列][entity なら entityId・eyeHeight・
     * destination の VarInt 3個][block なら位置][tick 数]。
     * 765の destination は 766に無いため、entityId と同じ値を書く。
     * 765の eyeHeight は minecraft-data では VarInt のため、float を
     * int にして書く（実バニラでの確認は未実施）。
     */
    private static void translateVibration766To765(Reader reader, Writer writer) {
        int positionType = reader.readVarInt();
        if (positionType == 0) {
            long position = reader.readPositionRaw();
            int ticks = reader.readVarInt();
            writer.writeString("minecraft:block");
            writer.writePositionRaw(position);
            writer.writeVarInt(ticks);
            return;
        }
        if (positionType == 1) {
            int entityId = reader.readVarInt();
            float eyeHeight = reader.readFloat();
            int ticks = reader.readVarInt();
            writer.writeString("minecraft:entity");
            writer.writeVarInt(entityId);
            writer.writeVarInt((int) eyeHeight);
            writer.writeVarInt(entityId);
            writer.writeVarInt(ticks);
            return;
        }
        throw new IllegalArgumentException("未知の vibration の位置種別です: " + positionType);
    }

    /** 音の Holder を766→765向けに書き直す。直書きの名前は 765の名前にする。 */
    private static void translateSoundHolder766To765(Reader reader, Writer writer) {
        int holder = reader.readVarInt();
        if (holder == 0) {
            writer.writeVarInt(0);
            writer.writeString(RegistryRemapper.mapSoundNameUp766(reader.readString()));
            boolean hasRange = reader.readBoolean();
            writer.writeBoolean(hasRange);
            if (hasRange) {
                writer.writeFloat(reader.readFloat());
            }
            return;
        }
        writer.writeVarInt(RegistryRemapper.mapSoundUp766(holder - 1) + 1);
    }

    /**
     * メタデータの値1個を766→765向けに変換する。型番号は 766のもの
     * （呼び出し側で 29／30 は 28／29 に付け替える）。テキスト（5／6）と
     * NBT（16）は765も名前なし NBT のためそのまま写す。スロット（7）は
     * 765形式に（コンポーネント付きは {@link DropPacketException}）、
     * 粒子（17／18）は 765の粒子形式にする。
     */
    private static void translateMetadataValue766To765(Reader reader, Writer writer, int type) {
        switch (type) {
            case 0 -> writer.writeByte(reader.readByte());
            case 1 -> writer.writeVarInt(reader.readVarInt());
            case 2 -> writer.writeVarLong(reader.readVarLong());
            case 3 -> writer.writeFloat(reader.readFloat());
            case 4 -> writer.writeString(reader.readString());
            case 5 -> {
                Tag tag = reader.readAnonymousNbt().tag();
                if (tag == null) {
                    throw new IllegalArgumentException("メタデータのテキストが空です。");
                }
                writer.writeAnonymousNbt(tag);
            }
            case 6 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    Tag tag = reader.readAnonymousNbt().tag();
                    if (tag == null) {
                        throw new IllegalArgumentException("メタデータのテキストが空です。");
                    }
                    writer.writeAnonymousNbt(tag);
                }
            }
            case 7 -> translateSlot766To765(reader, writer);
            case 8 -> writer.writeBoolean(reader.readBoolean());
            case 9 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            case 10 -> writer.writePositionRaw(reader.readPositionRaw());
            case 11 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writePositionRaw(reader.readPositionRaw());
                }
            }
            case 12 -> writer.writeVarInt(reader.readVarInt());
            case 13 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writeBytes(reader.readBytes(16));
                }
            }
            case 14 -> writer.writeVarInt(RegistryRemapper.mapBlockStateUp766(reader.readVarInt()));
            case 15 -> {
                // 0 は「無し」。それ以外はブロック状態ID。
                int state = reader.readVarInt();
                writer.writeVarInt(state == 0 ? 0 : RegistryRemapper.mapBlockStateUp766(state));
            }
            case 16 -> writeOptionalAnonymousNbt(writer, reader.readAnonymousNbt().tag());
            case 17 -> translateParticle766To765(reader, writer);
            case 18 -> {
                int count = reader.readVarInt();
                writer.writeVarInt(count);
                for (int i = 0; i < count; i++) {
                    translateParticle766To765(reader, writer);
                }
            }
            case 19 -> {
                writer.writeVarInt(reader.readVarInt());
                writer.writeVarInt(reader.readVarInt());
                writer.writeVarInt(reader.readVarInt());
            }
            case 20 -> writer.writeVarInt(reader.readVarInt());
            case 21 -> writer.writeVarInt(reader.readVarInt());
            case 27 -> writer.writeVarInt(reader.readVarInt());
            case 25 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writeString(reader.readString());
                    writer.writePositionRaw(reader.readPositionRaw());
                }
            }
            case 29 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            case 30 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            default -> throw new IllegalArgumentException("未知のメタデータ型です: " + type);
        }
    }

    /**
     * Entity Metadata（766 → 765）。型番号 29／30 は 28／29 に付け替える。
     * 766の 28（armadillo_state）は 765に無いためエントリごと落とす。
     * コンポーネント付きスロットや holder 直書き（構造化データ）の
     * エントリがある場合は {@code null} を返し、呼び出し側はパケットごと
     * 落とすこと（766形式のバイトを 765側に素通しするとずれるため）。
     */
    public static byte[] translateEntityMetadata766To765(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            Writer writer = new Writer();
            writer.writeVarInt(reader.readVarInt());
            while (true) {
                int index = reader.readUnsignedByte();
                if (index == 0xFF) {
                    writer.writeUnsignedByte(0xFF);
                    break;
                }
                int type = reader.readVarInt();
                // 766の 28（armadillo_state）は 765に無いため落とす。
                if (type == 28) {
                    reader.readVarInt();
                    continue;
                }
                // variant 系（22 猫・24 カエル）は VarInt のまま通す。
                if (type == 22 || type == 24) {
                    int variant = reader.readVarInt();
                    writer.writeUnsignedByte(index);
                    writer.writeVarInt(type);
                    writer.writeVarInt(variant);
                    continue;
                }
                // holder 形式（23 狼・26 絵画）は番号のものだけ通す。
                // 直書き（0）は構造化データのため読み飛ばせず、パケットごと落とす。
                // 狼は 765には pale（1）しか無いため、1以外も 1 にする。
                if (type == 23 || type == 26) {
                    int holder = reader.readVarInt();
                    if (holder == 0) {
                        throw new DropPacketException(
                                "766のメタデータの holder 直書き（構造化データ）を765向けに"
                                        + "変換できません（読み飛ばせないため）。");
                    }
                    writer.writeUnsignedByte(index);
                    writer.writeVarInt(type);
                    writer.writeVarInt(type == 23 && holder != 1 ? 1 : holder);
                    continue;
                }
                writer.writeUnsignedByte(index);
                writer.writeVarInt(type == 29 ? 28 : type == 30 ? 29 : type);
                translateMetadataValue766To765(reader, writer, type);
            }
            requireEnd(reader);
            return writer.bytes();
        } catch (DropPacketException e) {
            LOG.warning("Entity Metadata を変換できないため落とします: " + e.getMessage());
            return null;
        } catch (IllegalArgumentException e) {
            LOG.warning("Entity Metadata を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /**
     * Chunk Data（766 → 765）のペイロードを変換する。
     * vault のブロックエンティティ（766の種別 43）は765に無いため
     * エントリごと落とす。ominous の trial_spawner の状態は
     * 765の trial_spawner（ominous なし）に無害化する。
     * 読めない場合は元のペイロードをそのまま返す。
     */
    public static byte[] translateChunkData766To765(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            int chunkX = reader.readInt();
            int chunkZ = reader.readInt();
            Nbt.ReadResult heightmaps = reader.readAnonymousNbt();
            int dataLength = reader.readVarInt();
            byte[] chunkData = reader.readBytes(dataLength);
            byte[] translatedSections = translateChunkSectionsUp766(chunkData);
            int blockEntityCount = reader.readVarInt();
            List<BlockEntityEntry> kept = new ArrayList<>();
            for (int i = 0; i < blockEntityCount; i++) {
                int packedXZ = reader.readUnsignedByte();
                int y = reader.readShort();
                int type = reader.readVarInt();
                Tag nbt = readOptionalAnonymousNbt(reader);
                int mapped = RegistryRemapper.mapBlockEntityTypeUp766(type);
                if (mapped == RegistryRemapper.DROP) {
                    LOG.warning("765に無いブロックエンティティ種別（766 type=" + type
                            + "）のエントリをチャンクから落とします。");
                    continue;
                }
                kept.add(new BlockEntityEntry(packedXZ, y, mapped, nbt));
            }
            byte[] lightData = reader.rest();
            Writer writer = new Writer();
            writer.writeInt(chunkX);
            writer.writeInt(chunkZ);
            if (heightmaps.tag() == null) {
                writer.writeByte(0);
            } else {
                writer.writeAnonymousNbt(heightmaps.tag());
            }
            writer.writeByteArray(translatedSections);
            writer.writeVarInt(kept.size());
            for (BlockEntityEntry entry : kept) {
                writer.writeUnsignedByte(entry.packedXZ());
                writer.writeShort(entry.y());
                writer.writeVarInt(entry.type());
                writeOptionalAnonymousNbt(writer, entry.nbt());
            }
            writer.writeBytes(lightData);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Chunk Data を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /** Block Change（766 → 765）：位置＋ブロック状態ID。 */
    public static byte[] translateBlockChange766To765(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            long position = reader.readPositionRaw();
            int state = reader.readVarInt();
            requireEnd(reader);
            Writer writer = new Writer();
            writer.writePositionRaw(position);
            writer.writeVarInt(RegistryRemapper.mapBlockStateUp766(state));
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Block Change を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /** Multi Block Change（766 → 765）。 */
    public static byte[] translateMultiBlockChange766To765(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            long chunkCoordinates = reader.readLong();
            int count = reader.readVarInt();
            if (count < 0) {
                throw new IllegalArgumentException("Multi Block Change の件数が負です: " + count);
            }
            Writer writer = new Writer();
            writer.writeLong(chunkCoordinates);
            writer.writeVarInt(count);
            for (int i = 0; i < count; i++) {
                int record = reader.readVarInt();
                int state = record >>> 12;
                int local = record & 0xFFF;
                writer.writeVarInt((RegistryRemapper.mapBlockStateUp766(state) << 12) | local);
            }
            requireEnd(reader);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Multi Block Change を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /**
     * Block Entity Data（766 → 765）。
     * 765に無い種別（vault）の場合は {@code null} を返し、
     * 呼び出し側はパケットごと落とすこと。
     */
    public static byte[] translateBlockEntityData766To765(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            long position = reader.readPositionRaw();
            int type = reader.readVarInt();
            Tag nbt = readOptionalAnonymousNbt(reader);
            requireEnd(reader);
            int mapped = RegistryRemapper.mapBlockEntityTypeUp766(type);
            if (mapped == RegistryRemapper.DROP) {
                LOG.warning("765に無いブロックエンティティ種別（766 type=" + type
                        + "）の Block Entity Data を落とします。");
                return null;
            }
            Writer writer = new Writer();
            writer.writePositionRaw(position);
            writer.writeVarInt(mapped);
            writeOptionalAnonymousNbt(writer, nbt);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Block Entity Data を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

