    /** Update Attributes（766 → 767）。属性IDを付け替え、修飾子の UUID を文字列にする。 */
    public static byte[] translateUpdateAttributes766To767(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            Writer writer = new Writer();
            writer.writeVarInt(reader.readVarInt()); // entityId
            int count = reader.readVarInt();
            Writer kept = new Writer();
            int keptCount = 0;
            for (int i = 0; i < count; i++) {
                int key = reader.readVarInt();
                double value = reader.readDouble();
                int modCount = reader.readVarInt();
                Writer mods = new Writer();
                for (int j = 0; j < modCount; j++) {
                    java.util.UUID uuid = reader.readUuid();
                    double amount = reader.readDouble();
                    int operation = reader.readByte();
                    mods.writeString(uuid.toString());
                    mods.writeDouble(amount);
                    mods.writeByte(operation);
                }
                int mapped = RegistryRemapper.mapAttribute766To767(key);
                if (mapped == RegistryRemapper.DROP) {
                    logOnce("update-attributes-drop-767",
                            "767に無い属性のプロパティを落とします（id=" + key + "）。");
                    continue;
                }
                kept.writeVarInt(mapped);
                kept.writeDouble(value);
                kept.writeVarInt(modCount);
                kept.writeBytes(mods.bytes());
                keptCount++;
            }
            writer.writeVarInt(keptCount);
            writer.writeBytes(kept.bytes());
            requireEnd(reader);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Update Attributes を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

