    /**
     * 成分1個を767→768向けに変換する。成分種別（kind）は呼び出し側が
     * 付け替えて書くため、ここでは中身だけを書く。落とす成分は {@code false} を返す。
     */
    private static boolean translateComponent767To768(Reader reader, Writer writer, int kind767) {
        switch (kind767) {
            case 9, 23 -> translateEnchantments767To768(reader, writer);
            case 12 -> translateAttributeModifiers767To768(reader, writer);
            case 13 -> translateCustomModelData767To768(reader, writer);
            case 20 -> translateFood767To768(reader, writer);
            case 29, 30, 52 -> translateSlotArray767To768(reader, writer);
            case 35 -> {
                return translateTrim767To768(reader, writer);
            }
            case 40 -> translateInstrument767To768(reader, writer);
            case 42 -> translateJukeboxPlayable767To768(reader, writer);
            case 48 -> translateNoteBlockSound767To768(reader, writer);
            case 49 -> translateBannerPatterns767To768(reader, writer);
            case 51 -> translatePotDecorations767To768(reader, writer);
            case 22 -> translateTool767To768(reader, writer);
            case 10, 11 -> translateItemBlockPredicates767To768(reader, writer);
            default -> copyComponentOpaque767(reader, writer, kind767);
        }
        return true;
    }

    /**
     * 成分1個を768→767向けに変換する。成分種別（kind）は呼び出し側が
     * 付け替えて書くため、ここでは中身だけを書く。落とす成分は {@code false} を返す。
     */
    private static boolean translateComponent768To767(Reader reader, Writer writer, int kind768) {
        switch (kind768) {
            case 10, 33 -> translateEnchantments768To767(reader, writer);
            case 13 -> translateAttributeModifiers768To767(reader, writer);
            case 14 -> translateCustomModelData768To767(reader, writer);
            case 21 -> translateFood768To767(reader, writer);
            case 39, 40, 62 -> translateSlotArray768To767(reader, writer);
            case 45 -> {
                return translateTrim768To767(reader, writer);
            }
            case 50 -> translateInstrument768To767(reader, writer);
            case 52 -> translateJukeboxPlayable768To767(reader, writer);
            case 58 -> translateNoteBlockSound768To767(reader, writer);
            case 59 -> translateBannerPatterns768To767(reader, writer);
            case 61 -> translatePotDecorations768To767(reader, writer);
            case 26 -> translateTool768To767(reader, writer);
            case 11, 12 -> translateItemBlockPredicates768To767(reader, writer);
            default -> copyComponentOpaque768(reader, writer, kind768);
        }
        return true;
    }

    /** 成分1個の中身だけを写す（767形式。翻訳不要な成分用）。 */
    private static void copyComponentOpaque767(Reader reader, Writer writer, int kind767) {
        int mark = reader.position();
        try {
            skipComponentData767(reader, kind767);
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("成分を読み飛ばせません（767 kind=" + kind767 + "）: " + e.getMessage(), e);
        }
        int end = reader.position();
        reader.rewind(end - mark);
        writer.writeBytes(reader.readBytes(end - mark));
    }

    /** 成分1個の中身だけを写す（768形式。翻訳不要な成分用）。 */
    private static void copyComponentOpaque768(Reader reader, Writer writer, int kind768) {
        int mark = reader.position();
        try {
            skipComponentData768(reader, kind768);
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("成分を読み飛ばせません（768 kind=" + kind768 + "）: " + e.getMessage(), e);
        }
        int end = reader.position();
        reader.rewind(end - mark);
        writer.writeBytes(reader.readBytes(end - mark));
    }

    /** enchantments／stored_enchantments を767→768向けに変換する（IDは同一、末尾の bool 付き）。 */
    private static void translateEnchantments767To768(Reader reader, Writer writer) {
        int count = reader.readVarInt();
        Writer kept = new Writer();
        int keptCount = 0;
        for (int i = 0; i < count; i++) {
            int id = reader.readVarInt();
            int level = reader.readVarInt();
            int mapped = RegistryRemapper.mapEnchantment767To768(id);
            if (mapped == RegistryRemapper.DROP) {
                logOnce("enchantment-drop-768",
                        "768に無いエンチャントを落とします（id=" + id + "）。");
                continue;
            }
            kept.writeVarInt(mapped);
            kept.writeVarInt(level);
            keptCount++;
        }
        writer.writeVarInt(keptCount);
        writer.writeBytes(kept.bytes());
        writer.writeBoolean(reader.readBoolean()); // showInTooltip
    }

