    /** 音の Holder（registryEntryHolder）を767→768向けに変換する。直書きは音の名前にし、参照は音IDを付け替える。 */
    private static void translateSoundHolder767To768(Reader reader, Writer writer) {
        int holder = reader.readVarInt();
        if (holder == 0) {
            writer.writeVarInt(0);
            writer.writeString(RegistryRemapper.mapSoundName767To768(reader.readString()));
            boolean hasRange = reader.readBoolean();
            writer.writeBoolean(hasRange);
            if (hasRange) {
                writer.writeFloat(reader.readFloat());
            }
            return;
        }
        writer.writeVarInt(RegistryRemapper.mapSound767To768(holder - 1) + 1);
    }

    /** 音の Holder（registryEntryHolder）を768→767向けに変換する。直書きは音の名前にし、参照は音IDを付け替える。 */
    private static void translateSoundHolder768To767(Reader reader, Writer writer) {
        int holder = reader.readVarInt();
        if (holder == 0) {
            writer.writeVarInt(0);
            writer.writeString(RegistryRemapper.mapSoundNameUp768(reader.readString()));
            boolean hasRange = reader.readBoolean();
            writer.writeBoolean(hasRange);
            if (hasRange) {
                writer.writeFloat(reader.readFloat());
            }
            return;
        }
        int mapped = RegistryRemapper.mapSoundUp768(holder - 1);
        writer.writeVarInt(mapped + 1);
    }

