    /**
     * banner_patterns を767→768向けに変換する。層ごとのパターン Holder の ID を付け替える。
     * 767の banner_patterns は直書きでも registryEntryHolder 形式（proto.yml 1.21.3 の
     * ItemSoundHolder 記述は minecraft-data の誤りと判断し、767形式を維持する）。
     */
    private static void translateBannerPatterns767To768(Reader reader, Writer writer) {
        int count = reader.readVarInt();
        Writer kept = new Writer();
        int keptCount = 0;
        for (int i = 0; i < count; i++) {
            int holder = reader.readVarInt();
            int colorId = reader.readVarInt();
            if (holder == 0) {
                kept.writeVarInt(0);
                kept.writeString(reader.readString()); // assetId
                kept.writeString(reader.readString()); // translationKey
                kept.writeVarInt(colorId);
                keptCount++;
                continue;
            }
            int mapped = RegistryRemapper.mapBannerPattern767To768(holder - 1);
            if (mapped == RegistryRemapper.DROP) {
                logOnce("banner-pattern-drop-768",
                        "768に無いバナーパターンの層を落とします（id=" + (holder - 1) + "）。");
                continue;
            }
            kept.writeVarInt(mapped + 1);
            kept.writeVarInt(colorId);
            keptCount++;
        }
        writer.writeVarInt(keptCount);
        writer.writeBytes(kept.bytes());
    }

