    /** 絵画バリアントの Holder を770→771向けに変換する。絵画は50種・同じ並びのため DROP にはならない（念のため）。 */
    private static boolean translatePaintingVariantHolder770To771(Reader reader, Writer writer) {
        int holder = reader.readVarInt();
        if (holder == 0) {
            writer.writeVarInt(0);
            writer.writeInt(reader.readInt());
            writer.writeInt(reader.readInt());
            writer.writeString(reader.readString());
            copyOptionalAnonymousNbt(reader, writer);
            copyOptionalAnonymousNbt(reader, writer);
            return true;
        }
        int mapped = RegistryRemapper.mapPaintingVariant770To771(holder - 1);
        if (mapped == RegistryRemapper.DROP) {
            logOnce("painting-variant-drop-771",
                    "771に無い絵画のメタデータを落とします（id=" + (holder - 1) + "）。");
            return false;
        }
        writer.writeVarInt(mapped + 1);
        return true;
    }

