    /** 直接パレットの long 列の中の各エントリをブロック状態／バイオームIDとして変換する（773→774）。 */
    private static void remapDirectEntries773To774(long[] longs, int bitsPerEntry, int entryCount, boolean blocks) {
        long mask = (1L << bitsPerEntry) - 1;
        // エントリは long の境界をまたぐことがある（bits が 64 を割り切らないとき）。
        // BitStorage.get と同じく、またぐ分は次の long の下位ビットから取る。
        // 旧式の「1 long あたり perLong 個を先頭から読む」は、またぐエントリの
        // 上位ビットを落として誤った値を返していた（2026-11-14）。
        int needed = (entryCount * bitsPerEntry + 63) / 64;
        if (longs.length < needed) {
            throw new IllegalArgumentException(
                    "直接パレットの Data Array 長が想定より短いです（渡された=" + longs.length + "、想定=" + needed + "）。");
        }
        int[] entries = new int[entryCount];
        int bitPos = 0;
        for (int index = 0; index < entryCount; index++) {
            int cellIndex = bitPos >> 6;
            int bitIndex = bitPos & 63;
            long low = longs[cellIndex];
            int entry;
            if (bitIndex + bitsPerEntry <= 64) {
                entry = (int) ((low >>> bitIndex) & mask);
            } else {
                int lowBits = 64 - bitIndex;
                long high = cellIndex + 1 < longs.length ? longs[cellIndex + 1] : 0L;
                entry = (int) (((low >>> bitIndex) | (high << lowBits)) & mask);
            }
            entries[index] = entry;
            bitPos += bitsPerEntry;
        }
        for (int i = 0; i < longs.length; i++) {
            longs[i] = 0L;
        }
        bitPos = 0;
        for (int index = 0; index < entryCount; index++) {
            int mapped = blocks
                    ? RegistryRemapper.mapBlockState773To774(entries[index])
                    : mapBiome773To774(entries[index]);
            int cellIndex = bitPos >> 6;
            int bitIndex = bitPos & 63;
            longs[cellIndex] |= ((long) mapped & mask) << bitIndex;
            if (bitIndex + bitsPerEntry > 64) {
                int lowBits = 64 - bitIndex;
                longs[cellIndex + 1] |= ((long) mapped & mask) >>> lowBits;
            }
            bitPos += bitsPerEntry;
        }
    }

    /** 直接パレットの long 列の中の各エントリをブロック状態／バイオームIDとして変換する（774→773）。 */
    private static void remapDirectEntries774To773(long[] longs, int bitsPerEntry, int entryCount, boolean blocks) {
        long mask = (1L << bitsPerEntry) - 1;
        // エントリは long の境界をまたぐことがある（bits が 64 を割り切らないとき）。
        // BitStorage.get と同じく、またぐ分は次の long の下位ビットから取る。
        // 旧式の「1 long あたり perLong 個を先頭から読む」は、またぐエントリの
        // 上位ビットを落として誤った値を返していた（2026-11-14）。
        int needed = (entryCount * bitsPerEntry + 63) / 64;
        if (longs.length < needed) {
            throw new IllegalArgumentException(
                    "直接パレットの Data Array 長が想定より短いです（渡された=" + longs.length + "、想定=" + needed + "）。");
        }
        int[] entries = new int[entryCount];
        int bitPos = 0;
        for (int index = 0; index < entryCount; index++) {
            int cellIndex = bitPos >> 6;
            int bitIndex = bitPos & 63;
            long low = longs[cellIndex];
            int entry;
            if (bitIndex + bitsPerEntry <= 64) {
                entry = (int) ((low >>> bitIndex) & mask);
            } else {
                int lowBits = 64 - bitIndex;
                long high = cellIndex + 1 < longs.length ? longs[cellIndex + 1] : 0L;
                entry = (int) (((low >>> bitIndex) | (high << lowBits)) & mask);
            }
            entries[index] = entry;
            bitPos += bitsPerEntry;
        }
        for (int i = 0; i < longs.length; i++) {
            longs[i] = 0L;
        }
        bitPos = 0;
        for (int index = 0; index < entryCount; index++) {
            int mapped = blocks
                    ? RegistryRemapper.mapBlockStateUp774(entries[index])
                    : mapBiomeUp774(entries[index]);
            int cellIndex = bitPos >> 6;
            int bitIndex = bitPos & 63;
            longs[cellIndex] |= ((long) mapped & mask) << bitIndex;
            if (bitIndex + bitsPerEntry > 64) {
                int lowBits = 64 - bitIndex;
                longs[cellIndex + 1] |= ((long) mapped & mask) >>> lowBits;
            }
            bitPos += bitsPerEntry;
        }
    }

