    /**
     * resolvable_profile を773⇔774でそのまま写す。773・774で形式は同一。
     * varint（0＝partial／1＝complete）＋本体＋PlayerSkinPatch。
     * partial：option name（string）、option UUID、properties
     * （varint 件数＋GameProfileProperty：string、string、option string）。
     * complete：UUID、name（string）、properties（同上）。
     * PlayerSkinPatch：option body（string）、option cape（string）、
     * option elytra（string）、option model（varint：0＝wide／1＝slim）。
     * 形式は mc-1.21.9-protocol.json／mc-1.21.11-protocol.json の
     * ResolvableProfile／PartialResolvableProfile／GameProfile／
     * GameProfileProperty／PlayerSkinPatch による。
     */
    private static void copyResolvableProfile(Reader reader, Writer writer) {
        int kind = reader.readVarInt();
        writer.writeVarInt(kind);
        if (kind == 0) {
            // partial
            copyOptionalString(reader, writer);
            copyOptionalUuid(reader, writer);
            copyGameProfileProperties(reader, writer);
        } else {
            // complete
            writer.writeUuid(reader.readUuid());
            writer.writeString(reader.readString());
            copyGameProfileProperties(reader, writer);
        }
        // PlayerSkinPatch
        copyOptionalString(reader, writer); // body
        copyOptionalString(reader, writer); // cape
        copyOptionalString(reader, writer); // elytra
        boolean hasModel = reader.readBoolean();
        writer.writeBoolean(hasModel);
        if (hasModel) {
            writer.writeVarInt(reader.readVarInt()); // model（0＝wide／1＝slim）
        }
    }

    /** GameProfileProperty の列（varint 件数＋（string、string、option string））をそのまま写す。 */
    private static void copyGameProfileProperties(Reader reader, Writer writer) {
        int count = reader.readVarInt();
        writer.writeVarInt(count);
        for (int i = 0; i < count; i++) {
            writer.writeString(reader.readString()); // name
            writer.writeString(reader.readString()); // value
            copyOptionalString(reader, writer); // signature
        }
    }

    /** option string（bool＋string）をそのまま写す。 */
    private static void copyOptionalString(Reader reader, Writer writer) {
        boolean present = reader.readBoolean();
        writer.writeBoolean(present);
        if (present) {
            writer.writeString(reader.readString());
        }
    }

    /** option UUID（bool＋UUID）をそのまま写す。 */
    private static void copyOptionalUuid(Reader reader, Writer writer) {
        boolean present = reader.readBoolean();
        writer.writeBoolean(present);
        if (present) {
            writer.writeUuid(reader.readUuid());
        }
    }

    // ------------------------------------------------------------------
    // 763 ⇔ 762（1.20／1.20.1 ⇔ 1.19.4）
    // パケットIDは同一、ペイロードの差は Chunk Data／Update Light の
    // trustEdges、Multi Block Change の suppressLightUpdates、
    // Open Sign／Update Sign の isFrontText のみ。レジストリは
    // RegistryRemapper の 763⇔762 の表で直接付け替える。
    // NBT は 762・763 ともに名前付きのため、スロットやブロックエンティティの
    // NBT はそのまま写す。エンティティメタデータの variant 系は 762・763
    // で形式が同一のため落とさない（765→763 では落としている）。
    // チャットは 762・763 とも署名付きで同一形式のため変換しない。
    // ------------------------------------------------------------------

    /** 762／763 の falling_block のエンティティ種別ID（両方 36）。 */
    static final int FALLING_BLOCK_762 = 36;

    /** 763のスロット1個を762向けに読む。NBT は名前付きのまま通す。 */
    private static void translateSlot763To762(Reader reader, Writer writer) {
        boolean present = reader.readBoolean();
        writer.writeBoolean(present);
        if (!present) {
            return;
        }
        writer.writeVarInt(RegistryRemapper.mapItem763To762(reader.readVarInt()));
        writer.writeByte(reader.readByte());
        writeOptionalNamedNbt(writer, readOptionalNamedNbt(reader));
    }

    /** 762のスロット1個を763向けに読む。NBT は名前付きのまま通す。 */
    private static void translateSlot762To763(Reader reader, Writer writer) {
        boolean present = reader.readBoolean();
        writer.writeBoolean(present);
        if (!present) {
            return;
        }
        writer.writeVarInt(RegistryRemapper.mapItem762To763(reader.readVarInt()));
        writer.writeByte(reader.readByte());
        writeOptionalNamedNbt(writer, readOptionalNamedNbt(reader));
    }

    /** Chunk Data（763 0x24 → 762 0x24）。trustEdges を末尾の光データの前に挿す。 */
    public static byte[] translateChunkData763To762(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            int chunkX = reader.readInt();
            int chunkZ = reader.readInt();
            Nbt.NamedResult heightmaps = reader.readNamedNbt();
            int dataLength = reader.readVarInt();
            byte[] chunkData = reader.readBytes(dataLength);
            byte[] translatedSections = translateChunkSections763To762(chunkData);
            int blockEntityCount = reader.readVarInt();
            List<BlockEntityEntry> kept = new ArrayList<>();
            for (int i = 0; i < blockEntityCount; i++) {
                int packedXZ = reader.readUnsignedByte();
                int y = reader.readShort();
                int type = reader.readVarInt();
                Tag nbt = readOptionalNamedNbt(reader);
                int mapped = RegistryRemapper.mapBlockEntityType763To762(type);
                if (mapped == RegistryRemapper.DROP) {
                    LOG.warning("762に無いブロックエンティティ種別（763 type=" + type
                            + "）のエントリをチャンクから落とします。");
                    continue;
                }
                kept.add(new BlockEntityEntry(packedXZ, y, mapped, nbt));
            }
            byte[] lightData = reader.rest();
            Writer writer = new Writer();
            writer.writeInt(chunkX);
            writer.writeInt(chunkZ);
            if (heightmaps.tag() == null) {
                writer.writeByte(0);
            } else {
                writer.writeNamedNbt("", heightmaps.tag());
            }
            writer.writeByteArray(translatedSections);
            writer.writeVarInt(kept.size());
            for (BlockEntityEntry entry : kept) {
                writer.writeUnsignedByte(entry.packedXZ());
                writer.writeShort(entry.y());
                writer.writeVarInt(entry.type());
                writeOptionalNamedNbt(writer, entry.nbt());
            }
            writer.writeBoolean(true); // trustEdges（762のみ）
            writer.writeBytes(lightData);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Chunk Data を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /** Chunk Data（762 0x24 → 763 0x24）。trustEdges を読んで落とす。 */
    public static byte[] translateChunkData762To763(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            int chunkX = reader.readInt();
            int chunkZ = reader.readInt();
            Nbt.NamedResult heightmaps = reader.readNamedNbt();
            int dataLength = reader.readVarInt();
            byte[] chunkData = reader.readBytes(dataLength);
            byte[] translatedSections = translateChunkSections762To763(chunkData);
            int blockEntityCount = reader.readVarInt();
            List<BlockEntityEntry> kept = new ArrayList<>();
            for (int i = 0; i < blockEntityCount; i++) {
                int packedXZ = reader.readUnsignedByte();
                int y = reader.readShort();
                int type = reader.readVarInt();
                Tag nbt = readOptionalNamedNbt(reader);
                int mapped = RegistryRemapper.mapBlockEntityType762To763(type);
                if (mapped == RegistryRemapper.DROP) {
                    LOG.warning("763に無いブロックエンティティ種別（762 type=" + type
                            + "）のエントリをチャンクから落とします。");
                    continue;
                }
                kept.add(new BlockEntityEntry(packedXZ, y, mapped, nbt));
            }
            reader.readBoolean(); // trustEdges（762のみ）
            byte[] lightData = reader.rest();
            Writer writer = new Writer();
            writer.writeInt(chunkX);
            writer.writeInt(chunkZ);
            if (heightmaps.tag() == null) {
                writer.writeByte(0);
            } else {
                writer.writeNamedNbt("", heightmaps.tag());
            }
            writer.writeByteArray(translatedSections);
            writer.writeVarInt(kept.size());
            for (BlockEntityEntry entry : kept) {
                writer.writeUnsignedByte(entry.packedXZ());
                writer.writeShort(entry.y());
                writer.writeVarInt(entry.type());
                writeOptionalNamedNbt(writer, entry.nbt());
            }
            writer.writeBytes(lightData);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Chunk Data を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /** チャンク内のセクション列を 763 → 762 向けに変換する。 */
    static byte[] translateChunkSections763To762(byte[] data) {
        return translateChunkSections762(data, true);
    }

    /** チャンク内のセクション列を 762 → 763 向けに変換する。 */
    static byte[] translateChunkSections762To763(byte[] data) {
        return translateChunkSections762(data, false);
    }

    /** チャンク内のセクション列を 763⇔762 向けに変換する。 */
    private static byte[] translateChunkSections762(byte[] data, boolean to762) {
        Reader reader = new Reader(data);
        Writer writer = new Writer();
        while (reader.remaining() > 0) {
            int blockCount = reader.readShort();
            writer.writeShort(blockCount);
            translatePalettedContainer762(reader, writer, true, to762);
            translatePalettedContainer762(reader, writer, false, to762);
        }
        return writer.bytes();
    }

    /**
     * パレット付きコンテナ1個を 763⇔762 向けに変換する。
     * ブロックはブロック状態ID、バイオームはバイオームIDを付け替える。
     * 762 の cherry_grove は 763 の meadow へ（その逆は meadow のまま）。
     */
    private static void translatePalettedContainer762(Reader reader, Writer writer, boolean blocks,
            boolean to762) {
        int bitsPerEntry = reader.readUnsignedByte();
        if (bitsPerEntry > 32) {
            throw new IllegalArgumentException("Bits Per Entry が大きすぎます: " + bitsPerEntry);
        }
        writer.writeUnsignedByte(bitsPerEntry);
        int entryCount = blocks ? 4096 : 64;
        if (bitsPerEntry == 0) {
            int value = reader.readVarInt();
            writer.writeVarInt(blocks
                    ? (to762 ? RegistryRemapper.mapBlockState763To762(value)
                            : RegistryRemapper.mapBlockState762To763(value))
                    : (to762 ? RegistryRemapper.mapBiome763To762(value)
                            : RegistryRemapper.mapBiome762To763(value)));
            int dataLength = reader.readVarInt();
            if (dataLength != 0) {
                throw new IllegalArgumentException(
                        "シングルパレットの Data Array 長が 0 ではありません: " + dataLength);
            }
            writer.writeVarInt(0);
            return;
        }
        boolean indirect = blocks ? bitsPerEntry <= 8 : bitsPerEntry <= 3;
        if (indirect) {
            int paletteLength = reader.readVarInt();
            if (paletteLength <= 0 || paletteLength > (1 << bitsPerEntry)) {
                throw new IllegalArgumentException("パレット長が不正です: " + paletteLength);
            }
            writer.writeVarInt(paletteLength);
            for (int i = 0; i < paletteLength; i++) {
                int value = reader.readVarInt();
                writer.writeVarInt(blocks
                        ? (to762 ? RegistryRemapper.mapBlockState763To762(value)
                                : RegistryRemapper.mapBlockState762To763(value))
                        : (to762 ? RegistryRemapper.mapBiome763To762(value)
                                : RegistryRemapper.mapBiome762To763(value)));
            }
            copyLongArray(reader, writer);
            return;
        }
        // 直接パレット：Data Array の中身がレジストリ番号そのもの。
        int dataLength = reader.readVarInt();// バニラの BitStorage はエントリを long の境界をまたいで連続して詰めるため、

        // long 数は (entryCount * bitsPerEntry + 63) / 64。旧式の

        // (entryCount + perLong - 1) / perLong（perLong = 64 / bits）は bits が 64 を

        // 割り切らないとき（3・5・6・7・9…）に多めに数え、後続のコンテナがずれて

        // 読めなくなる（2026-11-14、26.1のBedrockマトリクスで発覚）。

        int expected = (entryCount * bitsPerEntry + 63) / 64;
        if (dataLength != expected) {
            throw new IllegalArgumentException("直接パレットの Data Array 長が想定と違います: "
                    + dataLength + "（想定=" + expected + "）。");
        }
        writer.writeVarInt(dataLength);
        long[] longs = new long[dataLength];
        for (int i = 0; i < dataLength; i++) {
            longs[i] = reader.readLong();
        }
        remapDirectEntries762(longs, bitsPerEntry, entryCount, blocks, to762);
        for (long value : longs) {
            writer.writeLong(value);
        }
    }

    /** 直接パレットの long 列の中の各エントリを 763⇔762 の番号に変換する。 */
    private static void remapDirectEntries762(long[] longs, int bitsPerEntry, int entryCount,
            boolean blocks, boolean to762) {
        long mask = (1L << bitsPerEntry) - 1;
        // エントリは long の境界をまたぐことがある（bits が 64 を割り切らないとき）。
        // BitStorage.get と同じく、またぐ分は次の long の下位ビットから取る。
        // 旧式の「1 long あたり perLong 個を先頭から読む」は、またぐエントリの
        // 上位ビットを落として誤った値を返していた（2026-11-14）。
        int needed = (entryCount * bitsPerEntry + 63) / 64;
        if (longs.length < needed) {
            throw new IllegalArgumentException(
                    "直接パレットの Data Array 長が想定より短いです（渡された=" + longs.length + "、想定=" + needed + "）。");
        }
        int[] entries = new int[entryCount];
        int bitPos = 0;
        for (int index = 0; index < entryCount; index++) {
            int cellIndex = bitPos >> 6;
            int bitIndex = bitPos & 63;
            long low = longs[cellIndex];
            int entry;
            if (bitIndex + bitsPerEntry <= 64) {
                entry = (int) ((low >>> bitIndex) & mask);
            } else {
                int lowBits = 64 - bitIndex;
                long high = cellIndex + 1 < longs.length ? longs[cellIndex + 1] : 0L;
                entry = (int) (((low >>> bitIndex) | (high << lowBits)) & mask);
            }
            entries[index] = entry;
            bitPos += bitsPerEntry;
        }
        for (int i = 0; i < longs.length; i++) {
            longs[i] = 0L;
        }
        bitPos = 0;
        for (int index = 0; index < entryCount; index++) {
            int mapped;
            if (blocks) {
                mapped = to762 ? RegistryRemapper.mapBlockState763To762(entries[index])
                        : RegistryRemapper.mapBlockState762To763(entries[index]);
            } else {
                mapped = to762 ? RegistryRemapper.mapBiome763To762(entries[index])
                        : RegistryRemapper.mapBiome762To763(entries[index]);
            }
            int cellIndex = bitPos >> 6;
            int bitIndex = bitPos & 63;
            longs[cellIndex] |= ((long) mapped & mask) << bitIndex;
            if (bitIndex + bitsPerEntry > 64) {
                int lowBits = 64 - bitIndex;
                longs[cellIndex + 1] |= ((long) mapped & mask) >>> lowBits;
            }
            bitPos += bitsPerEntry;
        }
    }

