    /**
     * パーティクル1個（ID VarInt＋データ）を 762⇔761 向けに変換する。
     * データを持つ粒子の番号は 761 と 762 で違うため、読み側の番号で分岐する。
     * 762：block=2、block_marker=3、falling_dust=25、dust=14、
     * dust_color_transition=15、sculk_charge=33、item=42、vibration=43、shriek=95。
     * 761：sculk_charge=30、item=39、vibration=40、shriek=92（他は同じ）。
     * 762 にしか無い cherry_leaves 系3種は white_ash へ写す（RegistryRemapper）。
     */
    private static void translateParticle761(Reader reader, Writer writer, boolean to761) {
        int particleId = reader.readVarInt();
        writer.writeVarInt(to761
                ? RegistryRemapper.mapParticle762To761(particleId)
                : RegistryRemapper.mapParticle761To762(particleId));
        if (to761) {
            switch (particleId) {
                case 2, 3, 25 -> // block, block_marker, falling_dust：ブロック状態ID
                        writer.writeVarInt(
                                RegistryRemapper.mapBlockState762To761(reader.readVarInt()));
                case 14 -> { // dust：赤・緑・青・大きさ
                    writer.writeFloat(reader.readFloat());
                    writer.writeFloat(reader.readFloat());
                    writer.writeFloat(reader.readFloat());
                    writer.writeFloat(reader.readFloat());
                }
                case 15 -> { // dust_color_transition：7個の float
                    for (int i = 0; i < 7; i++) {
                        writer.writeFloat(reader.readFloat());
                    }
                }
                case 33 -> writer.writeFloat(reader.readFloat()); // sculk_charge：回転
                case 42 -> translateSlot762To761(reader, writer); // item
                case 43 -> { // vibration：位置種別＋行き先＋tick 数
                    String positionType = reader.readString();
                    writer.writeString(positionType);
                    if ("minecraft:entity".equals(positionType)) {
                        writer.writeVarInt(reader.readVarInt());
                        writer.writeVarInt(reader.readVarInt());
                    }
                    if ("minecraft:block".equals(positionType)) {
                        writer.writePositionRaw(reader.readPositionRaw());
                    } else if ("minecraft:entity".equals(positionType)) {
                        writer.writeVarInt(reader.readVarInt());
                    }
                    writer.writeVarInt(reader.readVarInt());
                }
                case 95 -> writer.writeVarInt(reader.readVarInt()); // shriek：遅延 tick 数
                default -> {
                    // その他の粒子にデータは無い。
                }
            }
            return;
        }
        switch (particleId) {
            case 2, 3, 25 -> // block, block_marker, falling_dust：ブロック状態ID
                    writer.writeVarInt(
                            RegistryRemapper.mapBlockState761To762(reader.readVarInt()));
            case 14 -> { // dust：赤・緑・青・大きさ
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            case 15 -> { // dust_color_transition：7個の float
                for (int i = 0; i < 7; i++) {
                    writer.writeFloat(reader.readFloat());
                }
            }
            case 30 -> writer.writeFloat(reader.readFloat()); // sculk_charge：回転
            case 39 -> translateSlot761To762(reader, writer); // item
            case 40 -> { // vibration：位置種別＋行き先＋tick 数
                String positionType = reader.readString();
                writer.writeString(positionType);
                if ("minecraft:entity".equals(positionType)) {
                    writer.writeVarInt(reader.readVarInt());
                    writer.writeVarInt(reader.readVarInt());
                }
                if ("minecraft:block".equals(positionType)) {
                    writer.writePositionRaw(reader.readPositionRaw());
                } else if ("minecraft:entity".equals(positionType)) {
                    writer.writeVarInt(reader.readVarInt());
                }
                writer.writeVarInt(reader.readVarInt());
            }
            case 92 -> writer.writeVarInt(reader.readVarInt()); // shriek：遅延 tick 数
            default -> {
                // その他の粒子にデータは無い。
            }
        }
    }

    /**
     * Entity Effect（762 0x6C → 761 0x68）。
     * エフェクトIDは 761・762 ともに 1ベースで同一順序のため付け替えない。
     * factorCodec は両方とも bool＋名前付き NBT。
     */
    public static byte[] translateEntityEffect762To761(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            int entityId = reader.readVarInt();
            int effectId = reader.readVarInt();
            int amplifier = reader.readByte();
            int duration = reader.readVarInt();
            int hideParticles = reader.readByte();
            boolean hasFactor = reader.readBoolean();
            Tag factorCodec = hasFactor ? reader.readNamedNbt().tag() : null;
            requireEnd(reader);
            Writer writer = new Writer();
            writer.writeVarInt(entityId);
            writer.writeVarInt(effectId);
            writer.writeByte(amplifier);
            writer.writeVarInt(duration);
            writer.writeByte(hideParticles);
            writer.writeBoolean(factorCodec != null);
            if (factorCodec != null) {
                writer.writeNamedNbt("", factorCodec);
            }
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Entity Effect を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

