    /**
     * Entity Metadata（761 0x4E → 760 0x50）。
     * 760・761 でメタデータの型番号と形式は同一のため、variant 系（22／23／24／26）も
     * 落とさず通す。スロット・ブロック状態・粒子だけ番号を付け替える。
     */
    public static byte[] translateEntityMetadata761To760(byte[] payload) {
        return translateEntityMetadata760(payload, true);
    }

    /** Entity Metadata（760 0x50 → 761 0x4E）。 */
    public static byte[] translateEntityMetadata760To761(byte[] payload) {
        return translateEntityMetadata760(payload, false);
    }

    /** Entity Metadata を 761⇔760 向けに変換する。 */
    private static byte[] translateEntityMetadata760(byte[] payload, boolean to760) {
        try {
            Reader reader = new Reader(payload);
            Writer writer = new Writer();
            writer.writeVarInt(reader.readVarInt());
            while (true) {
                int index = reader.readUnsignedByte();
                if (index == 0xFF) {
                    writer.writeUnsignedByte(0xFF);
                    break;
                }
                int type = reader.readVarInt();
                writer.writeUnsignedByte(index);
                writer.writeVarInt(type);
                translateMetadataValue760(reader, writer, type, to760);
            }
            requireEnd(reader);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Entity Metadata を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

    /**
     * メタデータの値1個を 761⇔760 向けに変換する。型番号は 760・761 で同一
     * （minecraft-data の protocol.json の entityMetadataItem で確認）。
     * チャットは両方とも JSON 文字列、NBT は両方とも名前付き。
     */
    private static void translateMetadataValue760(Reader reader, Writer writer, int type,
            boolean to760) {
        switch (type) {
            case 0 -> writer.writeByte(reader.readByte());
            case 1 -> writer.writeVarInt(reader.readVarInt());
            case 2 -> writer.writeVarLong(reader.readVarLong());
            case 3 -> writer.writeFloat(reader.readFloat());
            case 4 -> writer.writeString(reader.readString());
            case 5 -> writer.writeString(reader.readString());
            case 6 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writeString(reader.readString());
                }
            }
            case 7 -> {
                if (to760) {
                    translateSlot761To760(reader, writer);
                } else {
                    translateSlot760To761(reader, writer);
                }
            }
            case 8 -> writer.writeBoolean(reader.readBoolean());
            case 9 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            case 10 -> writer.writePositionRaw(reader.readPositionRaw());
            case 11 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writePositionRaw(reader.readPositionRaw());
                }
            }
            case 12 -> writer.writeVarInt(reader.readVarInt());
            case 13 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writeBytes(reader.readBytes(16));
                }
            }
            case 14 -> writer.writeVarInt(to760
                    ? RegistryRemapper.mapBlockState761To760(reader.readVarInt())
                    : RegistryRemapper.mapBlockState760To761(reader.readVarInt()));
            case 15 -> {
                int state = reader.readVarInt();
                writer.writeVarInt(state == 0 ? 0 : (to760
                        ? RegistryRemapper.mapBlockState761To760(state)
                        : RegistryRemapper.mapBlockState760To761(state)));
            }
            case 16 -> writeOptionalNamedNbt(writer, readOptionalNamedNbt(reader));
            case 17 -> translateParticle760(reader, writer, to760);
            case 18 -> {
                // 村人データ（種別・職業・レベル）。
                writer.writeVarInt(reader.readVarInt());
                writer.writeVarInt(reader.readVarInt());
                writer.writeVarInt(reader.readVarInt());
            }
            case 19 -> writer.writeVarInt(reader.readVarInt());
            case 20 -> writer.writeVarInt(reader.readVarInt());
            case 21 -> writer.writeVarInt(reader.readVarInt());
            case 22 -> writer.writeVarInt(reader.readVarInt());
            case 23 -> {
                boolean present = reader.readBoolean();
                writer.writeBoolean(present);
                if (present) {
                    writer.writeString(reader.readString());
                    writer.writePositionRaw(reader.readPositionRaw());
                }
            }
            case 24 -> writer.writeVarInt(reader.readVarInt());
            case 25 -> writer.writeVarInt(reader.readVarInt());
            case 26 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            case 27 -> {
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
                writer.writeFloat(reader.readFloat());
            }
            default -> throw new IllegalArgumentException("未知のメタデータ型です: " + type);
        }
    }

    /** 音の Holder を 761 → 760 向けに読んで書き直す。 */
    /** 音の Holder（761）→ 音ID（760）に読んで書き直す。inline（名前）の場合は 760 のレジストリで名前を引き、無ければ GENERIC_SOUND_760 にする。range は 760 には無いため読んで落とす。 */
    private static void translateSoundHolder761To760(Reader reader, Writer writer) {
        int holder = reader.readVarInt();
        if (holder == 0) {
            String name = RegistryRemapper.mapSoundName761To760(reader.readString());
            boolean hasRange = reader.readBoolean();
            if (hasRange) {
                reader.readFloat();
            }
            int id = RegistryRemapper.soundIdForName760(name);
            writer.writeVarInt(id < 0 ? RegistryRemapper.GENERIC_SOUND_760 : id);
            return;
        }
        writer.writeVarInt(RegistryRemapper.mapSound761To760(holder - 1));
    }

    /** 音ID（760）→ 音の Holder（761）に読んで書き直す。 */
    private static void translateSoundHolder760To761(Reader reader, Writer writer) {
        int soundId = reader.readVarInt();
        writer.writeVarInt(RegistryRemapper.mapSound760To761(soundId) + 1);
    }

    /** Entity Sound Effect の音の Holder（761）→ 音ID（760）。inline（resource）の場合は名前で引く。range は 760 には無いため読んで落とす。 */
    private static void translateEntitySoundHolder761To760(Reader reader, Writer writer) {
        int holder = reader.readVarInt();
        if (holder == 0) {
            String name = RegistryRemapper.mapSoundName761To760(reader.readString());
            if (reader.readBoolean()) { // range（option f32）
                reader.readFloat();
            }
            int id = RegistryRemapper.soundIdForName760(name);
            writer.writeVarInt(id < 0 ? RegistryRemapper.GENERIC_SOUND_760 : id);
            return;
        }
        writer.writeVarInt(RegistryRemapper.mapSound761To760(holder - 1));
    }

    /** Entity Sound Effect の音ID（760）→ 音の Holder（761）。 */
    private static void translateEntitySoundHolder760To761(Reader reader, Writer writer) {
        int soundId = reader.readVarInt();
        writer.writeVarInt(RegistryRemapper.mapSound760To761(soundId) + 1);
    }

    /** Named Sound Effect（760 0x17）→ Sound Effect（761）。名前を Holder の inline 形式にする（range 無し）。 */
    public static byte[] translateNamedSoundEffect760To761(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            String name = reader.readString();
            int category = reader.readVarInt();
            int x = reader.readInt();
            int y = reader.readInt();
            int z = reader.readInt();
            float volume = reader.readFloat();
            float pitch = reader.readFloat();
            long seed = reader.readLong();
            requireEnd(reader);
            Writer writer = new Writer();
            writer.writeVarInt(0); // inline
            writer.writeString(RegistryRemapper.mapSoundName760To761(name));
            writer.writeBoolean(false); // range 無し
            writer.writeVarInt(category);
            writer.writeInt(x);
            writer.writeInt(y);
            writer.writeInt(z);
            writer.writeFloat(volume);
            writer.writeFloat(pitch);
            writer.writeLong(seed);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Named Sound Effect を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

