    /**
     * Stop Sound（761 0x5F → 760 0x61）。
     * flags の bit 0 は音源（VarInt）、bit 1 は音の名前（文字列）。
     * 名前は 761に無い音なら代替の音の名前にする。
     */
    public static byte[] translateStopSound761To760(byte[] payload) {
        try {
            Reader reader = new Reader(payload);
            int flags = reader.readByte();
            Writer writer = new Writer();
            writer.writeByte(flags);
            if ((flags & 0x01) != 0) {
                writer.writeVarInt(reader.readVarInt());
            }
            if ((flags & 0x02) != 0) {
                writer.writeString(RegistryRemapper.mapSoundName761To760(reader.readString()));
            }
            requireEnd(reader);
            return writer.bytes();
        } catch (IllegalArgumentException e) {
            LOG.warning("Stop Sound を変換できなかったため素通しします: " + e.getMessage());
            return payload;
        }
    }

