            int button = reader.readUnsignedByte();
            reader.readShort(); // actionNumber（758 には無い）
            int mode = reader.readVarInt();
            Writer itemWriter = new Writer();
            translateSlot498To758(reader, itemWriter);
            byte[] item = itemWriter.bytes();
            requireEnd(reader);
