    /** スロットの added／removed 成分部分だけを774→775向けに変換する。 */
    private static void translateSlotComponents774To775(Reader reader, Writer writer) {
        int added = reader.readVarInt();
        Writer kept = new Writer();
        int keptCount = 0;
        for (int i = 0; i < added; i++) {
            int kind774 = reader.readVarInt();
            int kind775 = mapComponentKind774To775(kind774);
            if (kind775 < 0) {
                skipComponentData774(reader, kind774);
                continue;
            }
            Writer component = new Writer();
            if (!translateComponent774To775(reader, component, kind774)) {
                continue;
            }
            kept.writeVarInt(kind775);
            kept.writeBytes(component.bytes());
            keptCount++;
        }
        writer.writeVarInt(keptCount);
        writer.writeBytes(kept.bytes());
        int removed = reader.readVarInt();
        Writer keptRemoved = new Writer();
        int keptRemovedCount = 0;
        for (int i = 0; i < removed; i++) {
            int kind775 = mapComponentKind774To775(reader.readVarInt());
            if (kind775 < 0) {
                continue;
            }
            keptRemoved.writeVarInt(kind775);
            keptRemovedCount++;
        }
        writer.writeVarInt(keptRemovedCount);
        writer.writeBytes(keptRemoved.bytes());
    }

    /** 774の成分種別を775の種別にする。775に無いものは -1（落とす）。 */
    private static int mapComponentKind774To775(int kind774) {
        if (kind774 < 0 || kind774 >= KIND_774_TO_775.length) {
            throw new IllegalArgumentException("未知の成分種別です（774）: " + kind774);
        }
        return KIND_774_TO_775[kind774];
    }

